def rising_readings(readings):
    n = len(readings)
    length = [1] * n
    for i in range(n):
        for j in range(i):
            if readings[j] < readings[i] and length[j] + 1 > length[i]:
                length[i] = length[j] + 1
    top = max(length)
    return [top, min(readings[i] for i in range(n) if length[i] == top)]

